UPDATE auth_governance.grant_projection o SET attempts=0,next_attempt_at=clock_timestamp(),last_error=NULL
FROM auth_governance.access_grant g WHERE g.id=o.grant_id AND g.id=#{id} AND g.version=#{version}
AND g.tenant_id=#{p.tenantId} AND g.application_id=#{p.applicationId} AND g.environment=#{p.environment}
AND o.grant_version=#{version} AND o.completed=false AND o.attempts=5
